class Solution {
  private static final long MOD = 1_000_000_007L;

  public int minNonZeroProduct(int p) {
    long max = (1L << p) - 1;
    long exponent = (1L << (p - 1)) - 1;
    return (int) (max % MOD * power(max - 1, exponent) % MOD);
  }

  private long power(long base, long exponent) {
    long result = 1;
    while (exponent > 0) {
      if ((exponent & 1) != 0) result = result * base % MOD;
      base = base * base % MOD;
      exponent >>= 1;
    }
    return result;
  }
}
